const format = function orderMessage({ body }) {
  const isHttpLink = (value) => {
    const parts =
      typeof value === "string" &&
      /^https?:\/\/(\[[0-9a-f:.]+\]|[^\s/\\?#@:%\[\]<>"`]+)(?::(\d{1,5}))?(?:[/?#][^\s\\]*)?$/i.exec(
        value,
      );
    return Boolean(
      parts && !/[\u0000-\u0020\u007f]/.test(value) && (!parts[2] || Number(parts[2]) <= 65535),
    );
  };
  const escape = (text) => text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  if (!Number.isSafeInteger(body.id) || body.id < 1)
    throw new Error("WooCommerce order ID is missing or invalid");
  for (const field of ["status", "total", "currency", "date_created", "transaction_id"])
    if (typeof body[field] !== "string") throw new Error("WooCommerce order is missing " + field);
  const href = body._links?.self?.[0]?.href;
  if (typeof href !== "string") throw new Error("WooCommerce order self link is missing");
  if (!isHttpLink(href)) throw new Error("Order link must be an HTTP(S) URL without credentials");
  const money =
    typeof body.currency_symbol === "string" && body.currency_symbol
      ? body.currency_symbol + body.total
      : body.currency + " " + body.total;
  const footer =
    "*Ordered:* " +
    escape(body.date_created) +
    " | *Transaction ID:* " +
    escape(body.transaction_id);
  if (footer.length > 300) throw new Error("Order metadata exceeds Slack footer size");
  const text = ":sparkles: There is a new order :sparkles:";
  return {
    text,
    attachments: [
      {
        color: "#66FF00",
        fallback: text,
        fields: [
          { title: "Order ID", value: String(body.id), short: true },
          { title: "Status", value: escape(body.status), short: true },
          { title: "Total", value: escape(money), short: true },
          { title: "Link", value: escape(href), short: false },
        ],
        footer,
      },
    ],
  };
};

return { json: format({ body: $json.body }) };

const read = function orderAmount({ body }) {
  if (
    typeof body.total !== "string" ||
    !/^\d+(?:\.\d+)?$/.test(body.total) ||
    !Number.isFinite(Number(body.total))
  )
    throw new Error("WooCommerce order total must be a nonnegative decimal string");
  if (typeof body.status !== "string" || !body.status)
    throw new Error("WooCommerce order status is missing");
  return { total: Number(body.total), status: body.status };
};

return { json: { body: $json, ...read({ body: $json }) } };
